  const heap = [];

  function swap(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  function parent(i) {
    return Math.floor((i - 1) / 2);
  }

  function left(i) {
    return 2 * i + 1;
  }

  function right(i) {
    return 2 * i + 2;
  }

  function bubbleUp(i) {
