      swap(i, parent(i));
      i = parent(i);
    }
  }

  function bubbleDown(i) {
    const n = heap.length;
    while (true) {
      let smallest = i;
      const l = left(i);
      const r = right(i);
      if (l < n && heap[l].priorite < heap[smallest].priorite) smallest = l;
      if (r < n && heap[r].priorite < heap[smallest].priorite) smallest = r;
      if (smallest === i) break;
      swap(i, smallest);
      i = smallest;
    }
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      bubbleUp(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      const min = heap[0];
      const end = heap.pop();
      if (heap.length > 0) {
        heap[0] = end;
        bubbleDown(0);
      }
      return min;
