function creerSubject() {
  const observers = [];

  function subscribe(observer) {
    if (!observer || typeof observer !== 'object') {
      return { unsubscribe() {} };
    }
    observers.push(observer);
    return {
      unsubscribe() {
        const index = observers.indexOf(observer);
        if (index !== -1) observers.splice(index, 1);
      }
    };
  }

  function next(value) {
    observers.forEach(o => {
      try { if (o.next) o.next(value); } catch (e) {}
    });
  }

  function error(err) {
    observers.forEach(o => {
      try { if (o.error) o.error(err); } catch (e) {}
    });
    observers.length = 0;
  }

  function complete() {
    observers.forEach(o => {
      try { if (o.complete) o.complete(); } catch (e) {}
    });
    observers.length = 0;
  }

  return { subscribe, next, error, complete };
}
