function trier_tableau(arr) {
  // Tri fusion bottom-up : O(n log n), sans utiliser Array.prototype.sort
  if (arr.length <= 1) return arr.slice();

  function merge(left, right) {
    const result = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      if (left[i] <= right[j]) {
        result.push(left[i++]);
      } else {
        result.push(right[j++]);
      }
    }
    while (i < left.length) result.push(left[i++]);
    while (j < right.length) result.push(right[j++]);
    return result;
  }

  const n = arr.length;
  let work = arr.slice();
  for (let size = 1; size < n; size *= 2) {
    for (let left = 0; left < n; left += 2 * size) {
      const mid = Math.min(left + size, n);
      const right = Math.min(left + 2 * size, n);
      const merged = merge(work.slice(left, mid), work.slice(mid, right));
      for (let k = 0; k < merged.length; k++) {
        work[left + k] = merged[k];
      }
    }
  }
  return work;
}
