function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  const CLOSED = 0;
  const OPEN = 1;
  const HALF_OPEN = 2;

  let state = CLOSED;
  let failures = 0;
  let resetTimer = null;

  function scheduleReset() {
    if (resetTimer) clearTimeout(resetTimer);
    resetTimer = setTimeout(() => {
      state = HALF_OPEN;
      resetTimer = null;
    }, delaiResetMs);
  }

  return async function (...args) {
    if (state === OPEN) {
      throw new Error('Circuit breaker is OPEN');
    }

    try {
      const result = await fn(...args);
      failures = 0;
      state = CLOSED;
      if (resetTimer) {
        clearTimeout(resetTimer);
        resetTimer = null;
      }
      return result;
    } catch (err) {
      failures += 1;
      if (failures >= seuil) {
        state = OPEN;
        scheduleReset();
      }
      throw err;
    }
  };
