function dijkstra(graphe, depart) {
  const distances = {};
  for (const noeud in graphe) distances[noeud] = Infinity;
  distances[depart] = 0;

  const tas = [[0, depart]];
  const visites = new Set();

  while (tas.length > 0) {
    let minIndex = 0;
    for (let i = 1; i < tas.length; i++) {
      if (tas[i][0] < tas[minIndex][0]) minIndex = i;
    }
    const [distance, noeud] = tas[minIndex];
    tas.splice(minIndex, 1);

    if (visites.has(noeud)) continue;
    visites.add(noeud);

    const voisins = graphe[noeud] || {};
    for (const voisin in voisins) {
      const nouvelleDistance = distance + voisins[voisin];
      if (nouvelleDistance < distances[voisin]) {
        distances[voisin] = nouvelleDistance;
        tas.push([nouvelleDistance, voisin]);
      }
    }
  }

  return distances;
}
